{"from":"a","to":"b","step":1,"packets":[["p1","vo",0,50,"ok",0,50,0],["p2","vo",0,30,"ok",50,80,50]],"endTime":80}
--- T2 two classes round robin, quantum large enough ---
{"from":"a","to":"b","step":10,"packets":[["v1","vo",0,10,"ok",0,100,0],["b1","be",0,10,"ok",100,200,100]],"endTime":200}
--- T3 quantum too small: vo head 60 q40 -> needs 2 visits, be served meanwhile? ---
{"from":"a","to":"b","step":1,"packets":[["v1","vo",0,60,"ok",10,70,10],["b1","be",0,10,"ok",0,10,0]],"endTime":70}
--- T4 capacity tail drop, cursor/deficit unchanged ---
{"from":"a","to":"b","step":1,"packets":[["v1","vo",0,60,"drop",null,null,null],["v2","vo",0,10,"ok",0,10,0],["b1","be",0,10,"ok",10,20,10]],"endTime":20}
--- T5 empty data ---
{"from":"a","to":"b","step":1,"packets":[],"endTime":0}
--- T6 future first arrival (idle jump) ---
{"from":"a","to":"b","step":2,"packets":[["v1","vo",7,5,"ok",7,17,0]],"endTime":17}

