--- T7 in-flight packet frees capacity; same-class arrival during tx admitted ---
{"from":"a","to":"b","step":1,"packets":[["v1","vo",0,60,"ok",0,60,0],["v2","vo",30,60,"ok",60,120,30]],"endTime":120}
--- T8 residual deficit allows back-to-back; otherwise needs a sweep ---
{"from":"a","to":"b","step":1,"packets":[["v1","vo",0,40,"ok",0,40,0],["v2","vo",0,40,"ok",40,80,40]],"endTime":80}
{"from":"a","to":"b","step":1,"packets":[["v1","vo",0,60,"ok",0,60,0],["v2","vo",0,60,"ok",60,120,60]],"endTime":120}
--- T9 same-instant: completion, then arrivals, then pick (arrival at depart time) ---
{"from":"a","to":"b","step":1,"packets":[["v1","vo",0,10,"ok",0,10,0],["b1","be",10,10,"ok",20,30,10],["v2","vo",10,10,"ok",10,20,0]],"endTime":30}
--- T10 idle between bursts ---
{"from":"a","to":"b","step":1,"packets":[["v1","vo",0,10,"ok",0,10,0],["b1","be",100,10,"ok",100,110,0]],"endTime":110}

